4	/// A Python integer literal. Represents both small (fits in an `i64`) and large integers.
5	#[derive(Clone, PartialEq, Eq, Hash)]
6	#[cfg_attr(feature = "get-size", derive(get_size2::GetSize))]
7	pub struct Int(Number);
