pub(crate) fn bad_file_permissions(checker: &Checker, call: &ast::ExprCall) {
    if !checker.semantic().seen_module(Modules::OS) {
        return;
    }

    if checker
        .semantic()
        .resolve_qualified_name(&call.func)
        .is_some_and(|qualified_name| matches!(qualified_name.segments(), ["os", "chmod"]))
    {
        if let Some(mode_arg) = call.arguments.find_argument_value("mode", 1) {
            let known = KnownBits::from_expr(mode_arg, checker.semantic());

            let dangerous_bits = if is_s103_extended_dangerous_bits_enabled(checker.settings()) {
                DANGEROUS_BITS_PREVIEW
            } else {
                DANGEROUS_BITS_STABLE
            };

            if known.oversized || (known.ones & !VALID_BITS) != 0 {
                // The mask is out of range (either it exceeds `u64::MAX`, or it sets bits outside
                // the valid Unix permission range). An oversized mask is reported as invalid even
                // if it would otherwise be permissive.
                checker.report_diagnostic(
                    BadFilePermissions {
                        reason: Reason::Invalid,
                    },
                    mode_arg.range(),
                );
            } else if (known.ones & dangerous_bits) != 0 {
                checker.report_diagnostic(
                    BadFilePermissions {
                        reason: Reason::Permissive(known.ones as u16),
                    },
                    mode_arg.range(),
                );
            }
        }
    }
}

/// The set of permission bits considered dangerous in stable mode: `S_IWOTH` and `S_IXGRP`.
const DANGEROUS_BITS_STABLE: u64 = 0o2 | 0o10;
/// The set of permission bits considered dangerous in preview mode: `S_IWOTH`, `S_IXGRP`,
/// `S_IXOTH`, and `S_IWGRP`.
const DANGEROUS_BITS_PREVIEW: u64 = 0o2 | 0o10 | 0o1 | 0o20;
/// The bits that make up a valid Unix permission mask (`0o7777`).
const VALID_BITS: u64 = 0o7777;

/// An abstract interpretation of the statically-known bits of a permission mask.
///
/// We only track which bits are *known to be set* (`ones`); any bit not in `ones` is treated as
/// unknown rather than known-to-be-zero. This is sufficient to soundly flag masks whose known bits
/// are dangerous, while conservatively ignoring masks whose value can't be determined statically.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct KnownBits {
    /// Bits statically known to be set.
    ones: u64,
    /// Whether the value is known to exceed `u64::MAX`.
    oversized: bool,
}

impl KnownBits {
    /// No bits are known to be set (an unknown value, or a value known to be zero).
    const UNKNOWN: Self = Self {
        ones: 0,
        oversized: false,
    };

    /// A value whose bits are exactly `value`.
    const fn exact(value: u64) -> Self {
        Self {
            ones: value,
            oversized: false,
        }
    }

    /// Abstractly interpret `expr` to determine its statically-known set bits.
    fn from_expr(expr: &Expr, semantic: &SemanticModel) -> Self {
        match expr {
            Expr::NumberLiteral(ast::ExprNumberLiteral {
                value: ast::Number::Int(int),
                ..
            }) => match int.as_u64() {
                Some(value) => Self::exact(value),
                // The literal exceeds `u64::MAX`.
                None => Self {
                    ones: 0,
                    oversized: true,
                },
            },
            Expr::Attribute(_) => semantic
                .resolve_qualified_name(expr)
                .as_ref()
                .and_then(py_stat)
                .map_or(Self::UNKNOWN, |value| Self::exact(u64::from(value))),
            Expr::BinOp(ast::ExprBinOp {
                left, op, right, ..
            }) => {
                let left_bits = Self::from_expr(left, semantic);
                let right_bits = Self::from_expr(right, semantic);
                match op {
                    // The set bits of an OR are the union of both operands' set bits; the result is
                    // oversized if either operand is.
                    Operator::BitOr => Self {
                        ones: left_bits.ones | right_bits.ones,
                        oversized: left_bits.oversized || right_bits.oversized,
                    },
                    // The set bits of an AND are the intersection of both operands' set bits; the
                    // result is oversized only if both operands are.
                    Operator::BitAnd => Self {
                        ones: left_bits.ones & right_bits.ones,
                        oversized: left_bits.oversized && right_bits.oversized,
                    },
                    // `x ^ x` is exactly zero when both sides are structurally identical with
                    // identical known bits. Any other XOR is left unknown.
                    Operator::BitXor => {
                        if left_bits == right_bits
                            && ComparableExpr::from(left) == ComparableExpr::from(right)
                        {
                            Self::exact(0)
                        } else {
                            Self::UNKNOWN
                        }
                    }
                    _ => Self::UNKNOWN,
                }
            }
            _ => Self::UNKNOWN,
        }
    }
